package api

import (
	"bytes"
	_ "embed"
	"html/template"
	"net/http"
	"strconv"

	"github.com/FairForge/vaultaire/internal/api/landing"
	"github.com/FairForge/vaultaire/internal/hosts"
	"github.com/FairForge/vaultaire/internal/usage"
)

//go:embed pricing.html
var pricingTemplateSrc string

// /pricing (WP-PRICE-1, Stage 1a Prompt 49): the pricing page, GENERATED by
// `make landing` from prices.json like the landing (pricing.src.html), so
// every number on it is the price file's (TestPricingPage_EveryNumberFrom
// PricesJSON). Rendered once per server in both signups variants, as the
// landing is; a web page view only — anything else at /pricing, and every
// request on the s3.* host, is the S3 API's (registerWebPages).

// pricingData is what pricing.src.html may print: the landing's fields and
// the free tier, which is the code's (usage.FreeTierLimits), not a price.
type pricingData struct {
	SignupsOpen     bool
	Web, Support    string
	FreeGB          int64
	FreeEgressGB    string
	FreeRatio       string
	EgressPastShort string
}

func mustRenderPricing(signupsOpen bool, h hosts.Hosts) []byte {
	tmpl := template.Must(template.New("pricing").Parse(pricingTemplateSrc))
	p := landing.Get()
	freeGB := usage.FreeTierLimits.StorageBytes / 1_000_000_000
	ratio := p.Egress.StandardFreeRatio
	var buf bytes.Buffer
	if err := tmpl.Execute(&buf, pricingData{
		SignupsOpen: signupsOpen, Web: h.Canonical, Support: h.SupportEmail(),
		FreeGB: freeGB, FreeEgressGB: trimRatio(float64(freeGB) * ratio), FreeRatio: trimRatio(ratio),
		EgressPastShort: p.Egress.PastAllowanceShort,
	}); err != nil {
		panic("render pricing page: " + err.Error())
	}
	return buf.Bytes()
}

// trimRatio prints a ratio or a size without trailing zeros (2, 10, 0.5).
func trimRatio(v float64) string { return strconv.FormatFloat(v, 'f', -1, 64) }

// pricingPage is the server's rendered variant (both rendered once).
func (s *Server) pricingPage(open bool) []byte {
	s.pricingOnce.Do(func() {
		h := s.hostSet()
		s.pricing = [2][]byte{mustRenderPricing(false, h), mustRenderPricing(true, h)}
	})
	if open {
		return s.pricing[1]
	}
	return s.pricing[0]
}

// handlePricing serves the page (registerWebPages mounts it behind webOnly).
func (s *Server) handlePricing(w http.ResponseWriter, r *http.Request) {
	page := s.pricingPage(s.flags != nil && s.flags.Enabled(flagSignups, ""))
	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	w.Header().Set("Cache-Control", "public, max-age=60")
	if r.Method == http.MethodHead {
		w.WriteHeader(http.StatusOK)
		return
	}
	_, _ = w.Write(page)
}
